import msal
import os


def handle_oauth_callback(payload, config=None):
    config = config or {}
    app = msal.ConfidentialClientApplication(
        os.environ.get("AZURE_CLIENT_ID"),
        authority=f"https://login.microsoftonline.com/{os.environ.get('AZURE_TENANT_ID')}",
        client_credential=os.environ.get("AZURE_CLIENT_SECRET")
    )

    result = app.acquire_token_by_authorization_code(
        payload['code'],
        scopes=config.get('scopes', ['User.Read']),
        redirect_uri=payload['redirect_uri']
    )

    if "access_token" in result:
        return {
            "access_token": result["access_token"],
            "id_token": result.get("id_token"),
            "expires_in": result["expires_in"]
        }
    else:
        raise Exception(f"Failed to acquire token: {result.get('error_description', 'Unknown error')}")

import os


def get_azure_ad_config():
    return {
        "client_id": os.environ.get("AZURE_CLIENT_ID"),
        "client_secret": os.environ.get("AZURE_CLIENT_SECRET"),
        "tenant_id": os.environ.get("AZURE_TENANT_ID"),
        "authority": f"https://login.microsoftonline.com/{os.environ.get('AZURE_TENANT_ID')}",
        "scopes": os.environ.get("AZURE_SCOPES", "User.Read").split()
    }


def get_redirect_uri():
    return os.environ.get("REDIRECT_URI", "http://localhost:8000/oauth_callback")

import os
import datetime
from google.cloud import firestore


def persist_audit_record(record: dict) -> dict:
    # Initialize Firestore DB client
    db = firestore.Client()

    # Reference to the 'audit_records' collection
    collection_ref = db.collection('federated_login_audit_records')

    # Add a timestamp to the record
    record['timestamp'] = datetime.datetime.now(datetime.timezone.utc)

    # Add the record to the collection
    try:
        doc_ref = collection_ref.add(record)
        return {"status": "success", "document_id": doc_ref[1].id}
    except Exception as e:
        return {"status": "error", "message": str(e)}
